const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
    // 1. Define geometry for California using TIGER dataset
    const california = ee.FeatureCollection('TIGER/2018/States')
        .filter(ee.Filter.eq('NAME', 'California'));

    // 2. Define date ranges
    const april2017_start = '2017-04-01';
    const april2017_end = '2017-04-30';
    const august2012_start = '2012-08-01';
    const august2012_end = '2012-08-31';

    // 3. Use ERA5-Land dataset for soil moisture (covers both periods)
    const dataset_id = 'ECMWF/ERA5_LAND/HOURLY';
    const soil_moisture_band = 'volumetric_soil_water_layer_1'; // 0-1 m³/m³

    // Function to get monthly mean soil moisture
    function getMonthlyMean(startDate, endDate, description) {
        const coll = ee.ImageCollection(dataset_id)
            .filterDate(startDate, endDate)
            .select(soil_moisture_band);

        const count = coll.size().getInfo();
        print(description + ' Images:', count);

        if (count === 0) {
            return null;
        }

        // Compute monthly mean
        const meanImg = coll.mean();

        // Count valid pixels in region
        const stats = meanImg.reduceRegion({
            reducer: ee.Reducer.count().combine({
                reducer2: ee.Reducer.mean(),
                sharedInputs: true
            }),
            geometry: california,
            scale: 10000, // 10km scale for ERA5
            maxPixels: 1e9
        });

        const pixelCount = stats.get('count').getInfo();
        const meanValue = stats.get('mean').getInfo();

        print(description + ' Valid Pixels:', pixelCount);
        print(description + ' Mean Soil Moisture:', meanValue);

        return {mean: meanValue, count: pixelCount};
    }

    // 4. Get data for both periods
    const april2017 = getMonthlyMean(april2017_start, april2017_end, 'April 2017');
    const august2012 = getMonthlyMean(august2012_start, august2012_end, 'August 2012');

    // 5. Check for data availability issues
    if (!april2017 || !august2012) {
        print('<answer>C1</answer>');
        return;
    }

    if (april2017.count === 0 || august2012.count === 0) {
        print('<answer>C2</answer>');
        return;
    }

    // 6. Validate results
    if (april2017.mean === null || august2012.mean === null || 
        isNaN(april2017.mean) || isNaN(august2012.mean)) {
        print('<answer>C3</answer>');
        return;
    }

    // Check for reasonable soil moisture range (0-1 m³/m³)
    if (april2017.mean < 0 || april2017.mean > 1 || 
        august2012.mean < 0 || august2012.mean > 1) {
        print('<answer>C3</answer>');
        return;
    }

    // 7. Compare and output final answer
    print('April 2017 Mean:', april2017.mean.toFixed(4));
    print('August 2012 Mean:', august2012.mean.toFixed(4));
    print('Difference:', (april2017.mean - august2012.mean).toFixed(4));

    if (april2017.mean > august2012.mean) {
        print('<answer>A</answer>');
    } else {
        print('<answer>B</answer>');
    }
}

async function initEE() {
    await new Promise((resolve, reject) => {
        ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
    });
    await new Promise((resolve, reject) => {
        ee.initialize(null, null, resolve, reject);
    });
    await runAnalysis();
}

initEE();
